7	import stripAnsi from 'strip-ansi';
8	
9	/**
10	 * Safely replaces text with literal strings, avoiding ECMAScript GetSubstitution issues.
11	 * Escapes $ characters to prevent template interpretation.
12	 */
13	export function safeLiteralReplace(
14	  str: string,
15	  oldString: string,
16	  newString: string,
17	): string {
18	  if (oldString === '' || !str.includes(oldString)) {
19	    return str;
20	  }
21	
22	  if (!newString.includes('$')) {
23	    return str.replaceAll(oldString, newString);
24	  }
25	
26	  const escapedNewString = newString.replaceAll('$', '$$$$');
27	  return str.replaceAll(oldString, escapedNewString);
28	}
29	
30	/**
31	 * Strips ANSI/VT escape sequences from a raw byte buffer.
32	 * Uses latin1 encoding to preserve every byte's value exactly (0-255)
33	 * while allowing string-based removal of escape sequences.
34	 */
35	export function stripAnsiFromBuffer(data: Buffer): Buffer {
36	  const stripped = stripAnsi(data.toString('latin1'));
37	  return Buffer.from(stripped, 'latin1');
38	}
39	
40	/**
41	 * Checks if a Buffer is likely binary by testing for the presence of a NULL byte.
42	 * The presence of a NULL byte is a strong indicator that the data is not plain text.
43	 * @param data The Buffer to check.
44	 * @param sampleSize The number of bytes from the start of the buffer to test.
45	 * @param isPtyOutput When true, ANSI escape sequences are stripped before
46	 *   checking and a null-byte ratio threshold is used instead of failing on
47	 *   a single null byte.  This prevents false positives caused by node-pty
48	 *   on Windows emitting VT control sequences that contain null bytes.
49	 * @returns True if the data is likely binary, false otherwise.
50	 */
51	export function isBinary(
52	  data: Buffer | null | undefined,
53	  sampleSize = 512,
54	  isPtyOutput = false,
55	): boolean {
56	  if (!data) {
57	    return false;
58	  }
59	
60	  let sample = data.length > sampleSize ? data.subarray(0, sampleSize) : data;
61	
62	  if (isPtyOutput) {
63	    sample = stripAnsiFromBuffer(sample);
64	    if (sample.length === 0) {
65	      return false;
66	    }
67	    let nullCount = 0;
68	    for (const byte of sample) {
69	      if (byte === 0) {
70	        nullCount++;
71	      }
72	    }
73	    return nullCount / sample.length > 0.1;
74	  }
75	
76	  for (const byte of sample) {
77	    // The presence of a NULL byte (0x00) is one of the most reliable
78	    // indicators of a binary file. Text files should not contain them.
79	    if (byte === 0) {
80	      return true;
81	    }
82	  }
83	
84	  // If no NULL bytes were found in the sample, we assume it's text.
85	  return false;
86	}
87	
88	/**
89	 * Detects the line ending style of a string.
90	 * @param content The string content to analyze.
91	 * @returns '\r\n' for Windows-style, '\n' for Unix-style.
92	 */
93	export function detectLineEnding(content: string): '\r\n' | '\n' {
94	  // If a Carriage Return is found, assume Windows-style endings.
95	  // This is a simple but effective heuristic.
96	  return content.includes('\r\n') ? '\r\n' : '\n';
97	}
98	
99	/**
100	 * Truncates a string to a maximum length, appending a suffix if truncated.
101	 * @param str The string to truncate.
102	 * @param maxLength The maximum length of the string.
103	 * @param suffix The suffix to append if truncated (default: '...[TRUNCATED]').
104	 * @returns The truncated string.
105	 */
106	export function truncateString(
107	  str: string,
108	  maxLength: number,
109	  suffix = '...[TRUNCATED]',
110	): string {
111	  if (str.length <= maxLength) {
112	    return str;
113	  }
114	
115	  // This regex matches a "Grapheme Cluster" manually:
116	  // 1. A surrogate pair OR a single character...
117	  // 2. Followed by any number of "Combining Marks" (\p{M})
118	  // 'u' flag is required for Unicode property escapes
119	  const graphemeRegex = /(?:[\uD800-\uDBFF][\uDC00-\uDFFF]|.)\p{M}*/gu;
120	
121	  let truncatedStr = '';
122	  let match: RegExpExecArray | null;
123	
124	  while ((match = graphemeRegex.exec(str)) !== null) {
125	    const segment = match[0];
126	
127	    // If adding the whole cluster (base char + accent) exceeds maxLength, stop.
128	    if (truncatedStr.length + segment.length > maxLength) {
129	      break;
130	    }
131	
132	    truncatedStr += segment;
133	    if (truncatedStr.length >= maxLength) break;
134	  }
135	
136	  // Final safety check for dangling high surrogates
137	  if (truncatedStr.length > 0) {
138	    const lastCode = truncatedStr.charCodeAt(truncatedStr.length - 1);
139	    if (lastCode >= 0xd800 && lastCode <= 0xdbff) {
140	      truncatedStr = truncatedStr.slice(0, -1);
141	    }
142	  }
143	
144	  return truncatedStr + suffix;
145	}
146	
147	/**
148	 * Safely replaces placeholders in a template string with values from a replacements object.
149	 * This performs a single-pass replacement to prevent double-interpolation attacks.
150	 *
151	 * @param template The template string containing {{key}} placeholders.
152	 * @param replacements A record of keys to their replacement values.
153	 * @returns The resulting string with placeholders replaced.
154	 */
155	export function safeTemplateReplace(
156	  template: string,
157	  replacements: Record<string, string>,
158	): string {
159	  // Regex to match {{key}} in the template string. The regex enforces string naming rules.
160	  const placeHolderRegex = /\{\{(\w+)\}\}/g;
161	  return template.replace(placeHolderRegex, (match, key) =>
162	    Object.prototype.hasOwnProperty.call(replacements, key)
163	      ? replacements[key]
164	      : match,
165	  );
166	}
167	
168	/**
169	 * Sanitizes output for injection into the model conversation.
170	 * Wraps output in a secure <output> tag and handles potential injection vectors
171	 * (like closing tags or template patterns) within the data.
172	 * @param output The raw output to sanitize.
173	 * @returns The sanitized string ready for injection.
174	 */
175	export function sanitizeOutput(output: string): string {
176	  const trimmed = output.trim();
177	  if (trimmed.length === 0) {
178	    return '';
179	  }
180	
181	  // Prevent direct closing tag injection.
182	  const escaped = trimmed.replaceAll('</output>', '&lt;/output&gt;');
183	  return `<output>\n${escaped}\n</output>`;
184	}
