26	/**
27	 * The separator used to qualify MCP tool names with their server prefix.
28	 * e.g. "mcp_server_name_tool_name"
29	 */
30	export const MCP_QUALIFIED_NAME_SEPARATOR = '_';
31	
32	/**
33	 * The strict prefix that all MCP tools must start with.
34	 */
35	export const MCP_TOOL_PREFIX = 'mcp_';
36	
37	/**
38	 * Returns true if `name` matches the MCP qualified name format: "mcp_server_tool",
39	 * i.e. starts with the "mcp_" prefix.
40	 */
41	export function isMcpToolName(name: string): boolean {
42	  return name.startsWith(MCP_TOOL_PREFIX);
43	}
44	
45	/**
46	 * Extracts the server name and tool name from a fully qualified MCP tool name.
47	 * Expected format: `mcp_{server_name}_{tool_name}`
48	 * @param name The fully qualified tool name.
49	 * @returns An object containing the extracted `serverName` and `toolName`, or
50	 *          `undefined` properties if the name doesn't match the expected format.
51	 */
52	export function parseMcpToolName(name: string): {
53	  serverName?: string;
54	  toolName?: string;
55	} {
56	  if (!isMcpToolName(name)) {
57	    return {};
58	  }
59	  // Remove the prefix
60	  const withoutPrefix = name.slice(MCP_TOOL_PREFIX.length);
61	  // The first segment is the server name, the rest is the tool name
62	  // Must be strictly `server_tool` where neither are empty
63	  const match = withoutPrefix.match(/^([^_]+)_(.+)$/);
64	  if (match) {
65	    return {
66	      serverName: match[1],
67	      toolName: match[2],
68	    };
69	  }
70	  return {};
71	}
72	
73	/**
74	 * Assembles a fully qualified MCP tool name (or wildcard pattern) from its server and tool components.
75	 *
76	 * @param serverName The backend MCP server name (can be '*' for global wildcards).
77	 * @param toolName The name of the tool (can be undefined or '*' for tool-level wildcards).
78	 * @returns The fully qualified name (e.g., `mcp_server_tool`, `mcp_*`, `mcp_server_*`).
79	 */
80	export function formatMcpToolName(
81	  serverName: string,
82	  toolName?: string,
83	): string {
84	  if (serverName === '*' && (toolName === undefined || toolName === '*')) {
85	    return `${MCP_TOOL_PREFIX}*`;
86	  } else if (serverName === '*') {
87	    return `${MCP_TOOL_PREFIX}*_${toolName}`;
88	  } else if (toolName === undefined || toolName === '*') {
89	    return `${MCP_TOOL_PREFIX}${serverName}_*`;
90	  } else {
91	    return `${MCP_TOOL_PREFIX}${serverName}_${toolName}`;
92	  }
93	}
