103	/**
104	 * Type guard to check if tool annotations implement McpToolAnnotation.
105	 */
106	export function isMcpToolAnnotation(
107	  annotation: unknown,
108	): annotation is McpToolAnnotation {
109	  if (typeof annotation !== 'object' || annotation === null) {
110	    return false;
111	  }
112	  // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
113	  const record = annotation as Record<string, unknown>;
114	  const serverName = record['_serverName'];
115	  return typeof serverName === 'string';
