765	  async execute({ abortSignal: signal }: ExecuteOptions): Promise<ToolResult> {
766	    if (this.context.config.getDirectWebFetch()) {
767	      return this.executeExperimental(signal);
768	    }
769	    const userPrompt = this.params.prompt!;
770	    const { validUrls } = parsePrompt(userPrompt);
771	
772	    const { toFetch, skipped } = this.filterAndValidateUrls(validUrls);
773	
774	    // If everything was skipped, fail early
775	    if (toFetch.length === 0 && skipped.length > 0) {
776	      const errorMessage = `All requested URLs were skipped: ${skipped.join(', ')}`;
777	      debugLogger.error(`[WebFetchTool] ${errorMessage}`);
778	      return {
779	        llmContent: `Error: ${errorMessage}`,
780	        returnDisplay: `Error: ${errorMessage}`,
781	        error: {
782	          message: errorMessage,
783	          type: ToolErrorType.WEB_FETCH_PROCESSING_ERROR,
784	        },
785	      };
786	    }
787	
788	    try {
789	      const geminiClient = this.context.geminiClient;
790	      const sanitizedPrompt = `Follow the user's instructions to process the authorized URLs.
791	
792	<user_instructions>
793	${sanitizeXml(userPrompt)}
794	</user_instructions>
795	
796	<authorized_urls>
797	${toFetch.join('\n')}
798	</authorized_urls>
799	`;
800	      const response = await geminiClient.generateContent(
801	        { model: 'web-fetch' },
802	        [{ role: 'user', parts: [{ text: sanitizedPrompt }] }],
803	        signal,
804	        LlmRole.UTILITY_TOOL,
805	      );
806	
807	      debugLogger.debug(
808	        `[WebFetchTool] Full response for prompt "${userPrompt.substring(
809	          0,
810	          50,
811	        )}...":`,
812	        JSON.stringify(response, null, 2),
813	      );
814	
815	      let responseText = getResponseText(response) || '';
816	      const groundingMetadata = response.candidates?.[0]?.groundingMetadata;
817	
818	      // Simple primary success check: we need some text or grounding data
